// exchange, written by hand (ARM64): X25519 (RFC 7748). The meaning is exchange/intent.md; the recorded checks are the judge.
// Generated by tools/x25519_asm.py, which only spells out the multiplication; nothing here was chosen by a compiler.
// Entries: x0 block, x1 numbers (16-bit), x2 how many, x3 argument, x4 call table.
// A number modulo 2^255 - 19 is four 64-bit limbs, lowest first, kept below 2^256. The same instructions run for every secret.
    .text
    .global public
    .global shared
// fe_mul: x0 where the product goes, x1 and x2 the two numbers. Uses x1-x17; keeps x19, x20 by saving them.
fe_mul:
    stp     x19, x20, [sp, #-16]!
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x1, #16]
    ldp     x7, x8, [x2]
    ldp     x9, x10, [x2, #16]
    mul     x19, x3, x7
    umulh   x20, x3, x7
    mov     x11, x19
    mov     x1, x20
    mul     x19, x4, x7
    umulh   x20, x4, x7
    adds    x12, x19, x1
    adc     x1, x20, xzr
    mul     x19, x5, x7
    umulh   x20, x5, x7
    adds    x13, x19, x1
    adc     x1, x20, xzr
    mul     x19, x6, x7
    umulh   x20, x6, x7
    adds    x14, x19, x1
    adc     x1, x20, xzr
    mov     x15, x1
    mul     x19, x3, x8
    umulh   x20, x3, x8
    adds    x12, x12, x19
    adc     x20, x20, xzr
    mov     x1, x20
    mul     x19, x4, x8
    umulh   x20, x4, x8
    adds    x13, x13, x19
    adc     x20, x20, xzr
    adds    x13, x13, x1
    adc     x1, x20, xzr
    mul     x19, x5, x8
    umulh   x20, x5, x8
    adds    x14, x14, x19
    adc     x20, x20, xzr
    adds    x14, x14, x1
    adc     x1, x20, xzr
    mul     x19, x6, x8
    umulh   x20, x6, x8
    adds    x15, x15, x19
    adc     x20, x20, xzr
    adds    x15, x15, x1
    adc     x1, x20, xzr
    mov     x16, x1
    mul     x19, x3, x9
    umulh   x20, x3, x9
    adds    x13, x13, x19
    adc     x20, x20, xzr
    mov     x1, x20
    mul     x19, x4, x9
    umulh   x20, x4, x9
    adds    x14, x14, x19
    adc     x20, x20, xzr
    adds    x14, x14, x1
    adc     x1, x20, xzr
    mul     x19, x5, x9
    umulh   x20, x5, x9
    adds    x15, x15, x19
    adc     x20, x20, xzr
    adds    x15, x15, x1
    adc     x1, x20, xzr
    mul     x19, x6, x9
    umulh   x20, x6, x9
    adds    x16, x16, x19
    adc     x20, x20, xzr
    adds    x16, x16, x1
    adc     x1, x20, xzr
    mov     x17, x1
    mul     x19, x3, x10
    umulh   x20, x3, x10
    adds    x14, x14, x19
    adc     x20, x20, xzr
    mov     x1, x20
    mul     x19, x4, x10
    umulh   x20, x4, x10
    adds    x15, x15, x19
    adc     x20, x20, xzr
    adds    x15, x15, x1
    adc     x1, x20, xzr
    mul     x19, x5, x10
    umulh   x20, x5, x10
    adds    x16, x16, x19
    adc     x20, x20, xzr
    adds    x16, x16, x1
    adc     x1, x20, xzr
    mul     x19, x6, x10
    umulh   x20, x6, x10
    adds    x17, x17, x19
    adc     x20, x20, xzr
    adds    x17, x17, x1
    adc     x1, x20, xzr
    mov     x2, x1
    mov     x3, #38
    mul     x19, x15, x3
    umulh   x20, x15, x3
    adds    x11, x11, x19
    adc     x1, x20, xzr
    mul     x19, x16, x3
    umulh   x20, x16, x3
    adds    x12, x12, x19
    adc     x20, x20, xzr
    adds    x12, x12, x1
    adc     x1, x20, xzr
    mul     x19, x17, x3
    umulh   x20, x17, x3
    adds    x13, x13, x19
    adc     x20, x20, xzr
    adds    x13, x13, x1
    adc     x1, x20, xzr
    mul     x19, x2, x3
    umulh   x20, x2, x3
    adds    x14, x14, x19
    adc     x20, x20, xzr
    adds    x14, x14, x1
    adc     x1, x20, xzr
    mul     x19, x1, x3
    adds    x11, x11, x19
    adcs    x12, x12, xzr
    adcs    x13, x13, xzr
    adcs    x14, x14, xzr
    csel    x19, x3, xzr, cs
    add     x11, x11, x19
    stp     x11, x12, [x0]
    stp     x13, x14, [x0, #16]
    ldp     x19, x20, [sp], #16
    ret
// fe_small: x0 = x1 times 121665
fe_small:
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x1, #16]
    mov     x7, #0xdb41
    movk    x7, #1, lsl #16
    mul     x11, x3, x7
    umulh   x8, x3, x7
    mul     x12, x4, x7
    umulh   x9, x4, x7
    adds    x12, x12, x8
    mul     x13, x5, x7
    umulh   x8, x5, x7
    adcs    x13, x13, x9
    mul     x14, x6, x7
    umulh   x9, x6, x7
    adcs    x14, x14, x8
    adc     x9, x9, xzr
    mov     x3, #38
    mul     x9, x9, x3
    adds    x11, x11, x9
    adcs    x12, x12, xzr
    adcs    x13, x13, xzr
    adcs    x14, x14, xzr
    csel    x9, x3, xzr, cs
    add     x11, x11, x9
    stp     x11, x12, [x0]
    stp     x13, x14, [x0, #16]
    ret
// fe_add: x0 = x1 + x2
fe_add:
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x1, #16]
    ldp     x7, x8, [x2]
    ldp     x9, x10, [x2, #16]
    adds    x3, x3, x7
    adcs    x4, x4, x8
    adcs    x5, x5, x9
    adcs    x6, x6, x10
    mov     x7, #38
    csel    x8, x7, xzr, cs             // past 2^256: that is 38
    adds    x3, x3, x8
    adcs    x4, x4, xzr
    adcs    x5, x5, xzr
    adcs    x6, x6, xzr
    csel    x8, x7, xzr, cs
    add     x3, x3, x8
    stp     x3, x4, [x0]
    stp     x5, x6, [x0, #16]
    ret
// fe_sub: x0 = x1 - x2
fe_sub:
    ldp     x3, x4, [x1]
    ldp     x5, x6, [x1, #16]
    ldp     x7, x8, [x2]
    ldp     x9, x10, [x2, #16]
    subs    x3, x3, x7
    sbcs    x4, x4, x8
    sbcs    x5, x5, x9
    sbcs    x6, x6, x10
    mov     x7, #38
    csel    x8, x7, xzr, cc             // below zero: take 38 off (which adds 2^256 back)
    subs    x3, x3, x8
    sbcs    x4, x4, xzr
    sbcs    x5, x5, xzr
    sbcs    x6, x6, xzr
    csel    x8, x7, xzr, cc
    sub     x3, x3, x8
    stp     x3, x4, [x0]
    stp     x5, x6, [x0, #16]
    ret
// fe_swap: exchange the numbers at x0 and x1 if x2 is all ones (it is all ones or zero); no branch on the secret
fe_swap:
    mov     x3, #0
1:  ldr     x4, [x0, x3, lsl #3]
    ldr     x5, [x1, x3, lsl #3]
    eor     x6, x4, x5
    and     x6, x6, x2
    eor     x4, x4, x6
    eor     x5, x5, x6
    str     x4, [x0, x3, lsl #3]
    str     x5, [x1, x3, lsl #3]
    add     x3, x3, #1
    cmp     x3, #4
    b.lo    1b
    ret

// the ladder's frame: saved registers (64), then 32-byte numbers
    .equ X1, 128
    .equ X2, 160
    .equ Z2, 192
    .equ X3, 224
    .equ Z3, 256
    .equ TA, 288
    .equ AA, 320
    .equ TB, 352
    .equ BB, 384
    .equ TE, 416
    .equ TC, 448
    .equ TD, 480
    .equ DA, 512
    .equ CB, 544
    .equ T0, 64
    .equ SCALAR, 96
    .equ LFRAME, 576
    .macro  FE op, dst, a, b
    add     x0, sp, #\dst
    add     x1, sp, #\a
    add     x2, sp, #\b
    bl      \op
    .endm
// x25519: x0 the secret (32 bytes), x1 the other side's value (32 bytes), x2 where the 32-byte answer goes
x25519:
    sub     sp, sp, #LFRAME
    stp     x29, x30, [sp]
    stp     x19, x20, [sp, #16]
    stp     x21, x22, [sp, #32]
    stp     x23, x24, [sp, #48]
    mov     x22, x2
    ldp     x3, x4, [x0]                // the secret, clamped as the standard says
    ldp     x5, x6, [x0, #16]
    and     x3, x3, #-8
    and     x6, x6, #0x7fffffffffffffff
    orr     x6, x6, #0x4000000000000000
    stp     x3, x4, [sp, #SCALAR]
    stp     x5, x6, [sp, #SCALAR + 16]
    ldp     x3, x4, [x1]                // their value, top bit ignored
    ldp     x5, x6, [x1, #16]
    and     x6, x6, #0x7fffffffffffffff
    stp     x3, x4, [sp, #X1]
    stp     x5, x6, [sp, #X1 + 16]
    stp     x3, x4, [sp, #X3]
    stp     x5, x6, [sp, #X3 + 16]
    mov     x3, #1
    stp     x3, xzr, [sp, #X2]
    stp     xzr, xzr, [sp, #X2 + 16]
    stp     xzr, xzr, [sp, #Z2]
    stp     xzr, xzr, [sp, #Z2 + 16]
    stp     x3, xzr, [sp, #Z3]
    stp     xzr, xzr, [sp, #Z3 + 16]
    mov     x19, #254                   // the bit being used
    mov     x20, #0                     // whether the two points are currently exchanged
l_step:
    lsr     x3, x19, #3
    add     x4, sp, #SCALAR
    ldrb    w3, [x4, x3]
    and     x5, x19, #7
    lsr     w3, w3, w5
    and     x21, x3, #1
    eor     x20, x20, x21
    neg     x23, x20
    add     x0, sp, #X2
    add     x1, sp, #X3
    mov     x2, x23
    bl      fe_swap
    add     x0, sp, #Z2
    add     x1, sp, #Z3
    mov     x2, x23
    bl      fe_swap
    mov     x20, x21
    FE      fe_add, TA, X2, Z2
    FE      fe_mul, AA, TA, TA
    FE      fe_sub, TB, X2, Z2
    FE      fe_mul, BB, TB, TB
    FE      fe_sub, TE, AA, BB
    FE      fe_add, TC, X3, Z3
    FE      fe_sub, TD, X3, Z3
    FE      fe_mul, DA, TD, TA
    FE      fe_mul, CB, TC, TB
    FE      fe_add, T0, DA, CB
    FE      fe_mul, X3, T0, T0
    FE      fe_sub, T0, DA, CB
    FE      fe_mul, T0, T0, T0
    FE      fe_mul, Z3, X1, T0
    FE      fe_mul, X2, AA, BB
    add     x0, sp, #T0
    add     x1, sp, #TE
    bl      fe_small
    FE      fe_add, T0, AA, T0
    FE      fe_mul, Z2, TE, T0
    subs    x19, x19, #1
    b.pl    l_step
    neg     x23, x20
    add     x0, sp, #X2
    add     x1, sp, #X3
    mov     x2, x23
    bl      fe_swap
    add     x0, sp, #Z2
    add     x1, sp, #Z3
    mov     x2, x23
    bl      fe_swap
    mov     x3, #1                      // 1 / z2 = z2 to the power 2^255 - 21: every bit set except those the byte 0xeb leaves clear
    stp     x3, xzr, [sp, #T0]
    stp     xzr, xzr, [sp, #T0 + 16]
    mov     x19, #254
l_inv:
    FE      fe_mul, T0, T0, T0
    cmp     x19, #8
    b.ge    1f
    mov     x3, #0xeb
    lsr     x3, x3, x19
    tbz     x3, #0, 2f
1:  FE      fe_mul, T0, T0, Z2
2:  subs    x19, x19, #1
    b.pl    l_inv
    FE      fe_mul, T0, X2, T0
    ldp     x3, x4, [sp, #T0]           // to the one true form below 2^255 - 19
    ldp     x5, x6, [sp, #T0 + 16]
    mov     x8, #19
    .rept   2
    lsr     x7, x6, #63
    and     x6, x6, #0x7fffffffffffffff
    mul     x7, x7, x8
    adds    x3, x3, x7
    adcs    x4, x4, xzr
    adcs    x5, x5, xzr
    adc     x6, x6, xzr
    .endr
    adds    x9, x3, #19
    adcs    x10, x4, xzr
    adcs    x11, x5, xzr
    adc     x12, x6, xzr
    tst     x12, #0x8000000000000000
    and     x12, x12, #0x7fffffffffffffff
    csel    x3, x9, x3, ne
    csel    x4, x10, x4, ne
    csel    x5, x11, x5, ne
    csel    x6, x12, x6, ne
    stp     x3, x4, [x22]
    stp     x5, x6, [x22, #16]
    ldp     x29, x30, [sp]
    ldp     x19, x20, [sp, #16]
    ldp     x21, x22, [sp, #32]
    ldp     x23, x24, [sp, #48]
    add     sp, sp, #LFRAME
    ret

// value_at: the 32-byte plain block at the handle in number x5, unless it is the block x6 -> x0 its bytes (0 if not usable). Uses x7, x8.
value_at:
    mov     x0, #0
    cmp     x2, x5
    b.le    9f
    ldrsh   x7, [x1, x5, lsl #1]
    cmp     x7, #0
    b.lt    9f
    cmp     x7, #255
    b.gt    9f
    add     x7, x7, #256
    ldr     x7, [x4, x7, lsl #3]
    cbz     x7, 9f
    ldr     w8, [x7]
    cmp     w8, #2
    b.ne    9f
    ldr     x8, [x7, #16]
    cmp     x8, #(64 + 32)
    b.ne    9f
    cmp     x7, x6
    b.eq    9f
    add     x0, x7, #64
9:  ret

public:
    sub     sp, sp, #96
    stp     x29, x30, [sp]
    str     x19, [sp, #16]
    mov     x19, x0
    mov     x6, x0
    mov     x5, #0
    bl      value_at
    cbz     x0, 1f
    ldr     x7, [x19, #16]
    cmp     x7, #96
    b.lo    1f
    mov     x3, #9                      // the standard starting point
    stp     x3, xzr, [sp, #32]
    stp     xzr, xzr, [sp, #48]
    add     x1, sp, #32
    add     x2, x19, #64
    bl      x25519
    mov     x0, #32
    b       2f
1:  mov     x0, #-1
2:  ldp     x29, x30, [sp]
    ldr     x19, [sp, #16]
    add     sp, sp, #96
    ret

shared:
    sub     sp, sp, #96
    stp     x29, x30, [sp]
    stp     x19, x20, [sp, #16]
    mov     x19, x0
    mov     x6, x0
    mov     x5, #0
    bl      value_at
    cbz     x0, 1f
    mov     x20, x0
    mov     x5, #1
    bl      value_at
    cbz     x0, 1f
    ldr     x7, [x19, #16]
    cmp     x7, #96
    b.lo    1f
    mov     x1, x0
    mov     x0, x20
    add     x2, sp, #32
    bl      x25519
    ldp     x3, x4, [sp, #32]
    ldp     x5, x6, [sp, #48]
    orr     x7, x3, x4
    orr     x7, x7, x5
    orr     x7, x7, x6
    cbz     x7, 1f                      // all zeros: one of the values that give every secret the same answer. Nothing is written.
    stp     x3, x4, [x19, #64]
    stp     x5, x6, [x19, #80]
    mov     x0, #32
    b       2f
1:  mov     x0, #-1
2:  ldp     x29, x30, [sp]
    ldp     x19, x20, [sp, #16]
    add     sp, sp, #96
    ret

